    if (offset < 0 || offset + 8 > this.length) {
        throw new IndexOutOfBoundsException("Invalid offset: " + offset);
    }

    // Read the long value from the input stream
    long value = 0;
    for (int i = 0; i < 8; i++) {
        value |= (long) (this.readByte(offset++) & 0xFF) << (i * 8);
    }

    return value;
}

