    double centerX = box.getMinX() + (box.getWidth() / 2.0);

    // Create two new boxes, one for each side of the center
    Box2D leftBox = new Box2D(box.getMinX(), box.getMinY(), centerX, box.getMaxY());
    Box2D rightBox = new Box2D(centerX, box.getMinY(), box.getMaxX(), box.getMaxY());

    // Return a pair with the two resulting boxes
    return new Pair<>(leftBox, rightBox);
}

