protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize the graph path with the first edge in the tour
    GraphPath<V, E> path = new GraphPath<>(graph, tour.iterator().next());

    // Iterate over the remaining edges in the tour
    for (E edge : tour) {
        // Add the edge to the graph path
        path.addEdge(edge);

        // Get the next edge in the tour
        E nextEdge = tour.iterator().next();

        // If the next edge is not the same as the current edge, add it to the graph path
        if (!edge.equals(nextEdge)) {
            path.addEdge(nextEdge);
        }
    }

    return path;
}

