public Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Initialize variables
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;

    // Iterate through the list of bounds
    for (int i = bounds.size() - 1; i >= 0; i--) {
        // Compute the suffix sum for the current bound
        int suffixSumForCurrentBound = 0;
        for (int j = i; j < bounds.size(); j++) {
            suffixSumForCurrentBound += bounds.get(j);
        }

        // Add the suffix sum to the list
        suffixSum.add(suffixSumForCurrentBound);

        // Update the sum
        sum += suffixSumForCurrentBound;
    }

    // Return the computed pair of suffix sum list and the sum of all elements
    return new Pair<>(suffixSum, sum);
}

