List<Integer> computeLowerBounds(List<K> keys) {
    // Initialize the lower bounds to the first key
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        lowerBounds.add(keys.get(i));
    }

    // Iterate over the keys and update the lower bounds
    for (int i = 1; i < keys.size(); i++) {
        K key = keys.get(i);
        int lowerBound = lowerBounds.get(i - 1);
        while (lowerBound < key && lowerBound < keys.get(lowerBound)) {
            lowerBound++;
        }
        lowerBounds.set(i, lowerBound);
    }

    return lowerBounds;
}

