public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder(str.length());
    int pos = 0;
    while (pos < str.length()) {
        char ch = str.charAt(pos);
        if (ch == '\\') {
            pos++;
            if (pos == str.length()) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            ch = str.charAt(pos);
            switch (ch) {
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '0':
                    sb.append((char) 0);
                    break;
                case 'u':
                    if (pos + 4 < str.length()) {
                        int codePoint = Integer.parseInt(str.substring(pos + 1, pos + 5), 16);
                        sb.append((char) codePoint);
                        pos += 4;
                    } else {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
        } else {
            sb.append(ch);
        }
        pos++;
    }
    return sb.toString();
}

