                    break;
                case 't':
                    sb.append('\t');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '0':
                    sb.append((char) 0);
                    break;
                case 'u':
                    if (pos + 4 < str.length()) {
                        int codePoint = Integer.parseInt(str.substring(pos + 1, pos + 5), 16);
                        sb.append((char) codePoint);
                        pos += 4;
                    } else {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
