public static String applyRelativePath(String path, String relativePath) {
    // Check if the path is null or empty
    if (path == null || path.isEmpty()) {
        return relativePath;
    }

    // Check if the relative path is null or empty
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Split the path into its individual components
    String[] pathComponents = path.split("/");

    // Split the relative path into its individual components
    String[] relativePathComponents = relativePath.split("/");

    // Create a new array to hold the combined path components
    String[] combinedPathComponents = new String[pathComponents.length + relativePathComponents.length - 1];

    // Copy the path components into the combined array
    System.arraycopy(pathComponents, 0, combinedPathComponents, 0, pathComponents.length);

    // Copy the relative path components into the combined array
    System.arraycopy(relativePathComponents, 1, combinedPathComponents, pathComponents.length, relativePathComponents.length - 1);

    // Join the combined path components using "/" as the separator
    return String.join("/", combinedPathComponents);
}

