private void enlarge(int size) {
    // Check if the current capacity is sufficient
    if (capacity - position >= size) {
        // If so, simply increase the position
        position += size;
    } else {
        // Otherwise, calculate the new capacity
        int newCapacity = (int) Math.max(capacity * 1.5, position + size);

        // Create a new byte array with the new capacity
        byte[] newData = new byte[newCapacity];

        // Copy the old data to the new array
        System.arraycopy(data, 0, newData, 0, position);

        // Set the new data and capacity
        data = newData;
        capacity = newCapacity;
    }
}

